    fun ensure(ctx: Context) {
        runCatching { patchGenuiThinking(ctx) }
            .onFailure { Log.w(TAG, "genui thinking patch failed: ${it.message}") }
    }

    private fun patched(text: String): String? {
        val block = START + CSS + END
        if (text.contains(START) && text.contains(END)) {
            val re = Regex(Regex.escape(START) + ".*?" + Regex.escape(END), RegexOption.DOT_MATCHES_ALL)
            val updated = re.replaceFirst(text, block)
            return if (updated == text) null else updated
        }
        val legacy = LEGACY + LEGACY_CSS
        if (text.contains(legacy)) return text.replaceFirst(legacy, block)
        if (text.contains(ANCHOR)) return text.replaceFirst(ANCHOR, ANCHOR + block)
        return null
    }

    private fun patchGenuiThinking(ctx: Context) {
        val profiles = File(EngineConfig.dshHome(ctx), "profiles")
        if (!profiles.isDirectory) return
        profiles.listFiles()?.forEach { profile ->
            val pkg = File(profile, "node_modules/dsh-genui")
            if (!pkg.isDirectory) return@forEach
            pkg.walkTopDown()
                .filter { it.isFile && it.name == "client.js" }
                .forEach { f ->
                    runCatching {
                        val text = f.readText()
                        val updated = patched(text) ?: return@runCatching
                        f.writeText(updated)
                        Log.i(TAG, "genui thinking patch applied: ${f.absolutePath}")
                    }.onFailure { Log.w(TAG, "genui patch skipped ${f.absolutePath}: ${it.message}") }
                }
        }
    }
}
